package com.google.gson.stream;

import com.google.gson.stream.JsonWriter;
import java.io.*;
import java.io.Closeable;
import java.io.Flushable;
import java.io.IOException;
import java.io.StringWriter;
import java.io.Writer;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class JsonWriter_value_TriageGen1Test {

    @Test
    public void testValueWithNonNullString() throws IOException {
        StringWriter writer = new StringWriter();
        JsonWriter jsonWriter = new JsonWriter(writer);
        jsonWriter.value("test");
        jsonWriter.flush();
        assertEquals("{\"test\":\"test\"}", writer.toString());
    }










}

package com.google.gson.stream;

import com.google.gson.stream.JsonWriter;
import java.io.*;
import java.io.Closeable;
import java.io.Flushable;
import java.io.IOException;
import java.io.StringWriter;
import java.io.Writer;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class JsonWriter_value_TriageGen1Test {



    @Test
    public void testValueWithEmptyString() throws IOException {
        StringWriter writer = new StringWriter();
        JsonWriter jsonWriter = new JsonWriter(writer);
        jsonWriter.beginObject();
        jsonWriter.name("empty");
        jsonWriter.value("");
        jsonWriter.endObject();
        jsonWriter.flush();
        assertEquals("{\"empty\":\"\"}", writer.toString());
    }








}

package com.google.gson.stream;

import com.google.gson.stream.JsonWriter;
