package com.google.gson.stream;

import com.google.gson.stream.JsonWriter;
import java.io.*;
import java.io.Closeable;
import java.io.Flushable;
import java.io.IOException;
import java.io.StringWriter;
import java.io.Writer;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class JsonWriter_value_TriageGen1Test {











    @Test
    public void testValueWithUnicodeCharacters() throws IOException {
        StringWriter writer = new StringWriter();
        JsonWriter jsonWriter = new JsonWriter(writer);
        jsonWriter.beginObject();
        jsonWriter.name("unicode");
        jsonWriter.value("Unicode: \u1234");
        jsonWriter.endObject();
        jsonWriter.flush();
        assertEquals("{\"unicode\":\"Unicode: \\u1234\"}", writer.toString());
    }
}
